    if not left_sidewalks:
        return image_patch

    people_on_left_sidewalk = []
    for person in people:
        for sidewalk in left_sidewalks:
            if person.overlaps_with(sidewalk.left, sidewalk.lower, sidewalk.right, sidewalk.upper):
                people_on_left_sidewalk.append(person)
                break

    if not people_on_left_sidewalk:
        return image_patch

